import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function AuthPage() {
  const navigate = useNavigate();
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loginIdentifier, setLoginIdentifier] = useState("");
  const [message, setMessage] = useState("");
  const [googleUser, setGoogleUser] = useState(null);
  const [currentPage, setCurrentPage] = useState("login");
  const [showForgot, setShowForgot] = useState(false);
  const [resetStep, setResetStep] = useState(1);
  const [resetEmail, setResetEmail] = useState("");
  const [resetCode, setResetCode] = useState("");
  const [resetNewPassword, setResetNewPassword] = useState("");
  const [resetConfirmNewPassword, setResetConfirmNewPassword] = useState("");

  const [role, setRole] = useState("employee");
  const [fullName, setFullName] = useState("");
  const [department, setDepartment] = useState("");
  const [managerId, setManagerId] = useState("");
  const [designation, setDesignation] = useState("associate");
  const [workCity, setWorkCity] = useState("");
  const [employeeId, setEmployeeId] = useState("");

  const [isLoading, setIsLoading] = useState(false);
  const [isLoginLoading, setIsLoginLoading] = useState(false);
  const [isRegisterLoading, setIsRegisterLoading] = useState(false);
  const [isResetLoading, setIsResetLoading] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) navigate("/profile");
  }, [navigate]);

  const isEmailValid = (value) => /[^\s@]+@[^\s@]+\.[^\s@]+/.test(value);
  const passHasLen = password.length >= 8;
  const passHasUpper = /[A-Z]/.test(password);
  const passHasLower = /[a-z]/.test(password);
  const passHasNumber = /\d/.test(password);
  const passHasSpecial = /[^A-Za-z0-9]/.test(password);
  const isPasswordStrong = passHasLen && passHasUpper && passHasLower && passHasNumber && passHasSpecial;

  const rPassHasLen = resetNewPassword.length >= 8;
  const rPassHasUpper = /[A-Z]/.test(resetNewPassword);
  const rPassHasLower = /[a-z]/.test(resetNewPassword);
  const rPassHasNumber = /\d/.test(resetNewPassword);
  const rPassHasSpecial = /[^A-Za-z0-9]/.test(resetNewPassword);
  const isResetPasswordStrong = rPassHasLen && rPassHasUpper && rPassHasLower && rPassHasNumber && rPassHasSpecial;

  const toMessageText = (value) => {
    if (value == null || value === undefined) return "";
    if (typeof value === "string") return value;
    if (typeof value === "number" || typeof value === "boolean") return String(value);
    try {
      if (typeof value === "object") {
        if (typeof value.detail === "string") return value.detail;
        if (typeof value.message === "string") return value.message;
        if (Array.isArray(value) && value.length > 0) {
          const first = value[0];
          if (typeof first === "string") return first;
          if (first && typeof first.msg === "string") return first.msg;
        }
      }
      return JSON.stringify(value);
    } catch {
      return String(value || "");
    }
  };

  const showSuccessMessage = (msg) => { const text = toMessageText(msg) || "Success"; setMessage(text); setTimeout(() => setMessage(""), 5000); };
  const showErrorMessage = (msg) => { const text = toMessageText(msg) || "An error occurred"; setMessage(text); setTimeout(() => setMessage(""), 7000); };

  const register = async () => {
    if (!username || !email || !password || !confirmPassword) { showErrorMessage("All fields are required"); return; }
    if (!isEmailValid(email)) { showErrorMessage("Please enter a valid email address"); return; }
    if (password !== confirmPassword) { showErrorMessage("Passwords do not match"); return; }
    if (!isPasswordStrong) { showErrorMessage("Please meet the password requirements below"); return; }

    setIsRegisterLoading(true);
    try {
      await axios.post("http://localhost:8000/register", { username, email, password, role, full_name: fullName, department, manager_id: managerId || null, designation, work_city: workCity, employee_id: employeeId || null });
      showSuccessMessage("Registration successful! Please login with your credentials.");
      setCurrentPage("login");
      setUsername(""); setEmail(""); setPassword(""); setConfirmPassword("");
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error registering");
    } finally {
      setIsRegisterLoading(false);
    }
  };

  const login = async () => {
    if (!loginIdentifier || !password) { showErrorMessage("Please enter your username or email and password"); return; }
    setIsLoginLoading(true);
    try {
      const payload = loginIdentifier.includes("@") ? { email: loginIdentifier, password } : { username: loginIdentifier, password };
      const res = await axios.post("http://localhost:8000/login", payload);
      const { access_token, message: resMessage } = res.data;
      if (!access_token) throw new Error("Empty access token received");
      localStorage.setItem("token", access_token);
      showSuccessMessage(resMessage);
      const profileRes = await axios.get("http://localhost:8000/profile", { headers: { Authorization: `Bearer ${access_token}` } });
      const role = profileRes?.data?.role || "employee";
      if (role === "manager") navigate("/team-bills"); else navigate("/profile");
    } catch (err) {
      const detail = err.response?.data?.detail || err.message || "Error logging in";
      showErrorMessage(detail);
      localStorage.removeItem("token");
    } finally {
      setIsLoginLoading(false);
    }
  };

  const sendResetCode = async () => {
    if (!resetEmail || !isEmailValid(resetEmail)) { showErrorMessage("Enter a valid email to receive a code"); return; }
    setIsResetLoading(true);
    try { await axios.post("http://localhost:8000/forgot-password", { email: resetEmail }); showSuccessMessage("If the email exists, a reset code has been sent. Check your inbox."); setResetStep(2); }
    catch { showSuccessMessage("If the email exists, a reset code has been sent. Check your inbox."); setResetStep(2); }
    finally { setIsResetLoading(false); }
  };

  const resetPassword = async () => {
    if (!resetCode || !resetNewPassword || !resetConfirmNewPassword) { showErrorMessage("All fields are required"); return; }
    if (resetNewPassword !== resetConfirmNewPassword) { showErrorMessage("Passwords do not match"); return; }
    if (!isResetPasswordStrong) { showErrorMessage("Please meet the password requirements below"); return; }
    setIsResetLoading(true);
    try { await axios.post("http://localhost:8000/reset-password", { email: resetEmail, code: resetCode, new_password: resetNewPassword }); showSuccessMessage("Password reset successful. Please login with your new password."); setShowForgot(false); setCurrentPage("login"); setLoginIdentifier(resetEmail); setResetEmail(""); setResetCode(""); setResetNewPassword(""); setResetConfirmNewPassword(""); }
    catch (err) { showErrorMessage(err.response?.data?.detail || "Unable to reset password. Check your code and try again."); }
    finally { setIsResetLoading(false); }
  };

  const handleGoogleResponse = async (response) => {
    setIsLoading(true);
    try {
      const credential = response.credential;
      const payload = JSON.parse(atob(credential.split('.')[1]));
      const googleUserInfo = { email: payload.email, name: payload.name };
      setGoogleUser(googleUserInfo);
      const res = await axios.post("http://localhost:8000/google-login", googleUserInfo);
      const { access_token, message: resMessage } = res.data;
      localStorage.setItem("token", access_token);
      showSuccessMessage(resMessage);
      navigate("/profile");
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error with Google Sign-In");
    } finally { setIsLoading(false); }
  };

  useEffect(() => {
    const fetchGoogleClientId = async () => {
      try {
        const response = await axios.get("http://localhost:8000/google-client-id");
        const clientId = response.data.client_id;
        if (window.google && clientId) {
          window.google.accounts.id.initialize({ client_id: clientId, callback: handleGoogleResponse });
          window.google.accounts.id.renderButton(document.getElementById("google-signin"), { theme: "outline", size: "large", text: "signin_with", shape: "rectangular" });
        }
      } catch (err) {
        console.error("Error fetching Google Client ID:", err);
        showErrorMessage("Error initializing Google Sign-In");
      }
    };
    fetchGoogleClientId();
  }, []);

  const getMessageClass = () => {
    if (!message) return "";
    const text = typeof message === "string" ? message : toMessageText(message);
    const safeText = typeof text === "string" ? text : String(text || "");
    const lower = safeText.toLowerCase();
    return (lower.includes("error") || lower.includes("fail") || lower.includes("invalid")) ? "message error" : "message success";
  };

  const switchToPage = (page) => {
    setCurrentPage(page); setMessage(""); setUsername(""); setEmail(""); setPassword(""); setConfirmPassword(""); setLoginIdentifier(""); setShowForgot(false); setResetStep(1); setResetEmail(""); setResetCode(""); setResetNewPassword(""); setResetConfirmNewPassword(""); setRole("employee"); setFullName(""); setDepartment(""); setManagerId(""); setDesignation("associate"); setWorkCity(""); setEmployeeId("");
  };

  return (
    <div className="container-page">
      <div className="container auth-page content-card">
        <div className="app-title">Secure Authentication</div>

        {/* Tabs */}
        <div className="page-tabs">
          <button className={`tab-button ${currentPage === 'login' ? 'active' : ''}`} onClick={() => switchToPage('login')}>Login</button>
          <button className={`tab-button ${currentPage === 'register' ? 'active' : ''}`} onClick={() => switchToPage('register')}>Register</button>
        </div>

        {message && <div className={getMessageClass()}>{message}</div>}

        {currentPage === 'login' && !showForgot && (
          <div>
            <div className="page-title">Welcome Back</div>
            <div className="page-description">Login with your username or email</div>
            <div className="form">
              <div className="form-group"><label className="form-label">Email or Username</label><input className="form-control" type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} placeholder="e.g., user@example.com or johndoe" /></div>
              <div className="form-group"><label className="form-label">Password</label><input className="form-control" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" /></div>
              <button className="btn btn-primary btn-block" onClick={login} disabled={isLoginLoading}>{isLoginLoading ? 'Signing in...' : 'Sign In'}</button>
              <div className="login-link"><button className="link-button" onClick={() => setShowForgot(true)}>Forgot Password?</button></div>
            </div>
            <div className="google-signin-container"><div id="google-signin"></div></div>
          </div>
        )}

        {currentPage === 'register' && (
          <div>
            <div className="page-title">Create your account</div>
            <div className="page-description">Join your team to submit and manage expenses</div>
            <div className="form">
              <div className="form-row columns-2">
                <div className="form-group"><label className="form-label">Username</label><input className="form-control" type="text" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="johndoe" /></div>
                <div className="form-group"><label className="form-label">Email</label><input className="form-control" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="user@example.com" /></div>
              </div>
              <div className="form-row columns-2">
                <div className="form-group"><label className="form-label">Password</label><input className="form-control" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" /></div>
                <div className="form-group"><label className="form-label">Confirm Password</label><input className="form-control" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="••••••••" /></div>
              </div>
              <div className="form-row columns-2">
                <div className="form-group"><label className="form-label">Role</label><select className="form-control" value={role} onChange={(e) => setRole(e.target.value)}><option value="employee">Employee</option><option value="manager">Manager</option></select></div>
                <div className="form-group"><label className="form-label">Full Name</label><input className="form-control" type="text" value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="John Doe" /></div>
              </div>
              <div className="form-row columns-2">
                <div className="form-group"><label className="form-label">Department</label><input className="form-control" type="text" value={department} onChange={(e) => setDepartment(e.target.value)} placeholder="Finance" /></div>
                <div className="form-group"><label className="form-label">Manager ID</label><input className="form-control" type="text" value={managerId} onChange={(e) => setManagerId(e.target.value)} placeholder="Optional" /></div>
              </div>
              <div className="form-row columns-2">
                <div className="form-group"><label className="form-label">Designation</label><input className="form-control" type="text" value={designation} onChange={(e) => setDesignation(e.target.value)} placeholder="Associate" /></div>
                <div className="form-group"><label className="form-label">Work City</label><input className="form-control" type="text" value={workCity} onChange={(e) => setWorkCity(e.target.value)} placeholder="Mumbai" /></div>
              </div>
              <div className="form-row columns-2">
                <div className="form-group"><label className="form-label">Employee ID</label><input className="form-control" type="text" value={employeeId} onChange={(e) => setEmployeeId(e.target.value)} placeholder="Optional" /></div>
              </div>
              <button className="btn btn-primary btn-block" onClick={register} disabled={isRegisterLoading}>{isRegisterLoading ? 'Creating account...' : 'Create Account'}</button>
            </div>
          </div>
        )}

        {showForgot && (
          <div>
            <div className="page-title">Reset your password</div>
            <div className="page-description">Enter your email to receive a reset code</div>
            <div className="form">
              {resetStep === 1 && (
                <>
                  <div className="form-group"><label className="form-label">Email</label><input className="form-control" type="email" value={resetEmail} onChange={(e) => setResetEmail(e.target.value)} placeholder="user@example.com" /></div>
                  <button className="btn btn-primary btn-block" onClick={sendResetCode} disabled={isResetLoading}>{isResetLoading ? 'Sending...' : 'Send reset code'}</button>
                </>
              )}
              {resetStep === 2 && (
                <>
                  <div className="form-group"><label className="form-label">Reset Code</label><input className="form-control" type="text" value={resetCode} onChange={(e) => setResetCode(e.target.value)} placeholder="Enter the 6-digit code" /></div>
                  <div className="form-row columns-2">
                    <div className="form-group"><label className="form-label">New Password</label><input className="form-control" type="password" value={resetNewPassword} onChange={(e) => setResetNewPassword(e.target.value)} placeholder="••••••••" /></div>
                    <div className="form-group"><label className="form-label">Confirm New Password</label><input className="form-control" type="password" value={resetConfirmNewPassword} onChange={(e) => setResetConfirmNewPassword(e.target.value)} placeholder="••••••••" /></div>
                  </div>
                  <button className="btn btn-primary btn-block" onClick={resetPassword} disabled={isResetLoading}>{isResetLoading ? 'Resetting...' : 'Reset Password'}</button>
                </>
              )}
              <div className="login-link"><button className="link-button" onClick={() => setShowForgot(false)}>Back to Login</button></div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default AuthPage;
